pub fn sorting_circuits(n: usize) -> Vec<(usize, usize)> {
    match n {
        0..=1 => Vec::new(),
        2..=64 => SORTERS[(n - 2) as usize]
            .iter()
            .map(|&(left, right)| (usize::from(left), usize::from(right)))
            .collect(),
        _ => todo!("Unavailable."),
    }
}
